41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
91	     *
92	     * @param e The {@link Exception} to be handled
93	     * @param request {@link HttpServletRequest} object referring to the current request.
94	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
95	     */
96	    @ExceptionHandler(Exception.class)
97	    @ResponseBody
98	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
99	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
100	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
101	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
102	        return ResponseEntity.status(status).body(detail);
103	    }
104	
105	    /**
106	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
107	     * method returns a 404 Not Found status if an entity does not exist.
108	     *
109	     * @param e The {@link DataIntegrityViolationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
112	     */
113	    @ExceptionHandler(DataIntegrityViolationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
116	        logger.warn("Data integrity violation at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getMessage());
120	        logger.debug("Data integrity violation stacktrace", e);
121	        HttpStatus status = HttpStatus.NOT_FOUND;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles exception thrown by Bean Validation on controller methods parameters
128	     *
129	     * @param e The {@link MethodArgumentNotValidException} to be handled
130	     * @param request {@link HttpServletRequest} object referring to the current request.
131	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
132	     */
133	    @ExceptionHandler(MethodArgumentNotValidException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
136	        HttpStatus status = HttpStatus.BAD_REQUEST;
137	        BindingErrorsResponse errors = new BindingErrorsResponse();
138	        BindingResult bindingResult = e.getBindingResult();
139	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
140	        if (bindingResult.hasErrors()) {
141	            errors.addAllErrors(bindingResult);
142	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
143	                .map(fieldError -> {
144	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
145	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
146	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
147	                        fieldError.getField(),
148	                        defaultMessage,
149	                        rejectedValue);
150	                    return new ValidationMessageDto(message)
151	                        .putAdditionalProperty("field", fieldError.getField())
152	                        .putAdditionalProperty("rejectedValue", rejectedValue)
153	                        .putAdditionalProperty("defaultMessage", defaultMessage);
154	                })
155	                .toList();
156	            logger.debug("Validation error at {} {}: {}",
157	                request.getMethod(),
158	                request.getRequestURI(),
159	                bindingResult.getFieldErrors());
160	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
161	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
162	                .map(FieldError::getField)
163	                .distinct()
164	                .toList();
165	            detail.setProperty("errors", invalidFields);
166	            return ResponseEntity.status(status).body(detail);
167	        }
168	        return ResponseEntity.status(status).body(detail);
169	    }
170	
171	}
